def fail(condition,message):
    if not condition:raise ValueError(message)
def sha(data):return hashlib.sha256(data).hexdigest()
def git(root,*args):
    return subprocess.check_output(['git',*args],cwd=root,text=True,stderr=subprocess.PIPE).strip()
def dump(root,name,data):
    p=root/name;p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(data,indent=2,sort_keys=True,ensure_ascii=False)+'\n',encoding='utf-8')
def load(root,name):return json.loads((root/name).read_text(encoding='utf-8'))
def timestamp():return datetime.now(timezone.utc).isoformat()

def safe_path(root,name):
    posix=PurePosixPath(name)
    fail(not posix.is_absolute() and bool(posix.parts) and all(x not in ('','..','.') for x in posix.parts),'Unsafe payload path')
    fail('\\' not in name and posix.parts[0] not in ('.git','.github') and ':' not in name,'Forbidden payload destination')
    p=root/name
    for ancestor in [p,*p.parents]:
        if ancestor==root.parent:break
        fail(not ancestor.is_symlink(),'Refusing symlink destination: '+name)
    return p

def decode_payload(encoded=None):
    try:
        raw=zlib.decompress(base64.b85decode(PAYLOAD_B85 if encoded is None else encoded))
        fail(sha(raw)==PAYLOAD_SHA256,'Embedded payload checksum mismatch')
        data=json.loads(raw)
        fail(data['schema_version']==1 and data['base_commit']==BASE and data['target_q']=='Q050','Payload identity mismatch')
        paths=set()
        for row in data['files']:
            fail(row['path'] not in paths,'Duplicate payload path');paths.add(row['path'])
            safe_path(Path.cwd().resolve(),row['path'])
            fail(sha(base64.b64decode(row['content_b64'],validate=True))==row['after_sha256'],'Payload file checksum mismatch')
        return data
    except (ValueError,KeyError,TypeError,zlib.error) as exc:
        raise ValueError('Invalid embedded Q050 payload: '+str(exc)) from exc

def check_history(root,payload):
    for name,digest in payload['protected_history'].items():
        p=safe_path(root,name)
        fail(p.is_file() and sha(p.read_bytes())==digest,'Protected historical bytes differ: '+name)
    expected={p for p in payload['protected_history'] if p.startswith('versions/accepted/')}
    observed={p.relative_to(root).as_posix() for p in (root/'versions/accepted').rglob('*') if p.is_file() and not p.relative_to(root).as_posix().startswith('versions/accepted/v0.12/')}
    fail(expected==observed,'Previous accepted snapshot inventory differs from pinned base')

def preflight(root,payload):
    root=root.resolve();fail(Path(git(root,'rev-parse','--show-toplevel')).resolve()==root,'Run at repository root')
    fail(git(root,'merge-base',BASE,'HEAD')==BASE,'Current branch must descend from pinned Q049 base')
    state=load(root,'accepted/model_state.json')
    current=state.get('current_q');version=state.get('accepted_model_version')
    fail((current,version) in [('Q049','v0.11'),('Q050','v0.12')],'Expected Q049/v0.11 or identical Q050/v0.12; refusing skip/downgrade')
    check_history(root,payload)
    changes=[]
    for row in payload['files']:
        p=safe_path(root,row['path']);actual=sha(p.read_bytes()) if p.is_file() else None
        if actual==row['after_sha256']:continue
        fail(current=='Q049','Existing Q050 installation differs from this frozen candidate: '+row['path'])
        fail(actual==row['before_sha256'],'Existing target differs from pinned Q049 input: '+row['path'])
        changes.append(row['path'])
    # Do not commit preexisting modifications, including unrelated operator edits.
    fail(not git(root,'status','--porcelain','--untracked-files=no'),'Checkout has tracked uncommitted changes')
    return changes

def candidate_digest(root):
    payload=decode_payload();items={}
    for row in payload['files']:
        p=safe_path(root,row['path']);fail(p.is_file() and sha(p.read_bytes())==row['after_sha256'],'Installed candidate differs: '+row['path'])
        items[row['path']]=row['after_sha256']
    check_history(root,payload)
    return sha(json.dumps(items,sort_keys=True,separators=(',',':')).encode())

def apply(root):
    root=Path(root).resolve();payload=decode_payload()
    # An immediate second invocation in the same staged checkout is a read-only no-op.
    state=load(root,'accepted/model_state.json')
    if state.get('current_q')=='Q050' and state.get('accepted_model_version')=='v0.12':
        digest=candidate_digest(root)
        previous=root/OUT/'PLAN.json'
        if previous.is_file():
            prior=json.loads(previous.read_text())
            if prior.get('head')==git(root,'rev-parse','HEAD') and prior.get('candidate_digest')==digest and prior.get('payload_sha256')==PAYLOAD_SHA256:
                return {**prior,'status':'ALREADY_INSTALLED'}
        changes=preflight(root,payload)
    else:changes=preflight(root,payload)
    head=git(root,'rev-parse','HEAD')
    for row in payload['files']:
        if row['path'] in changes:
            p=safe_path(root,row['path']);p.parent.mkdir(parents=True,exist_ok=True)
            p.write_bytes(base64.b64decode(row['content_b64'],validate=True))
    digest=candidate_digest(root)
    report={'schema_version':1,'status':'APPLIED_CANDIDATE' if changes else 'ALREADY_INSTALLED','target_q':'Q050','candidate_version':'v0.12','scientific_scope':'Closed conditional existence only; no uniqueness, native fidelity, smallness or Q048 completion','head':head,'pinned_base':BASE,'candidate_input_base':SOURCE_CANDIDATE,'candidate_digest':digest,'payload_sha256':PAYLOAD_SHA256,'changed_paths':changes,'created_at_utc':timestamp(),'historical_scientific_checks_rerun':False,'remote_write_performed':False}
    dump(root,OUT+'/PLAN.json',report)
    print(json.dumps({k:report[k] for k in ['status','target_q','candidate_version','candidate_digest']}))
    return report

def validate(root):
    root=Path(root).resolve();plan=load(root,OUT+'/PLAN.json')
    fail(git(root,'rev-parse','HEAD')==plan['head'],'HEAD changed after staging')
    digest=candidate_digest(root)
    fail(digest==plan['candidate_digest'],'Candidate digest changed')
    protected={p.relative_to(root).as_posix():sha(p.read_bytes()) for folder in ['accepted','candidate','model','evidence','versions/accepted','release'] for p in (root/folder).rglob('*') if p.is_file()}
    commands=[('q050',[sys.executable,'tests/programs/q050_model_validate.py']),('campaign',[sys.executable,'tests/programs/model_campaign.py','validate']),('unittest',[sys.executable,'-m','unittest','discover','-v','-s','tests/programs']),('healthcheck',[sys.executable,'tests/programs/model_campaign.py','test'])]
    rows=[]
    for label,command in commands:
        result=subprocess.run(command,cwd=root,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        text=result.stdout;log=root/OUT/(label+'.log');log.write_text(text,encoding='utf-8')
        rows.append({'name':label,'command':command,'exit_code':result.returncode,'log':log.relative_to(root).as_posix(),'log_sha256':sha(log.read_bytes())})
        print(text[-14000:],flush=True)
        if result.returncode:break
    after={name:sha((root/name).read_bytes()) for name in protected}
    passed=len(rows)==len(commands) and all(x['exit_code']==0 for x in rows) and protected==after
    report={'schema_version':1,'status':'PASS' if passed else 'FAIL','head':plan['head'],'candidate_digest':digest,'checks':rows,'protected_files':len(protected),'scientific_state_unchanged_by_checks':protected==after,'historical_scientific_checks_rerun':False,'time_utc':timestamp(),'remote_write_performed':False}
    dump(root,OUT+'/VALIDATION.json',report)
    fail(passed,'Validation failed; see uploaded q050-model-v012 artifacts. No release push is permitted.')
    return report

def remote_head(root,branch):
    lines=git(root,'ls-remote','--exit-code','origin','refs/heads/'+branch).splitlines()
    fail(len(lines)==1,'Cannot resolve exactly one target branch')
    return lines[0].split()[0]

def verify_origin(root):
    """Constrain both resolved Git read/write destinations to the intended repository."""
    fetch=git(root,'remote','get-url','--all','origin').splitlines()
    push=git(root,'remote','get-url','--push','--all','origin').splitlines()
    fail(len(fetch)==1 and len(push)==1,'Exactly one origin fetch and push destination is required')
    allowed={
        'https://github.com/Morfindien/bubbleverse-model',
        'https://github.com/Morfindien/bubbleverse-model.git',
        'git@github.com:Morfindien/bubbleverse-model.git',
        'ssh://git@github.com/Morfindien/bubbleverse-model.git',
    }
    fail(fetch[0] in allowed and push[0] in allowed,'Resolved origin fetch/push URL must identify '+REPOSITORY)
    return {'fetch_url':fetch[0],'push_url':push[0]}

def verify_staged_candidate(root):
    """Check the actual Git blobs, including any clean-filter transformations."""
    for row in decode_payload()['files']:
        blob=subprocess.check_output(['git','show',':'+row['path']],cwd=root,stderr=subprocess.PIPE)
        fail(sha(blob)==row['after_sha256'],'Staged Git bytes differ from validated candidate: '+row['path'])
    return git(root,'write-tree')

def publish(root,branch,environment=None):
    root=Path(root).resolve();env=os.environ if environment is None else environment
    fail(env.get('GITHUB_ACTIONS')=='true' and env.get('GITHUB_EVENT_NAME')=='workflow_dispatch','Publishing requires a manual GitHub Actions dispatch')
    fail(env.get('GITHUB_REPOSITORY')==REPOSITORY,'Wrong destination repository')
    fail(env.get('GITHUB_REF')=='refs/heads/'+branch,'Dispatch ref must equal destination branch')
    verify_origin(root)
    subprocess.run(['git','check-ref-format','refs/heads/'+branch],cwd=root,check=True,stdout=subprocess.DEVNULL)
    event=json.loads(Path(env['GITHUB_EVENT_PATH']).read_text())
    fail(event.get('inputs',{}).get('mode')=='install','Select mode=install in the manual dispatch')
    run=env.get('GITHUB_RUN_ID','');attempt=env.get('GITHUB_RUN_ATTEMPT','')
    fail(run.isdigit() and attempt.isdigit(),'Missing numeric Actions run identity')
    plan=load(root,OUT+'/PLAN.json');verification=load(root,OUT+'/VALIDATION.json')
    fail(verification['status']=='PASS' and verification['head']==plan['head'],'Successful validation of this exact HEAD required')
    fail(candidate_digest(root)==verification['candidate_digest']==plan['candidate_digest'],'Candidate changed since validation')
    fail(git(root,'rev-parse','HEAD')==plan['head'],'HEAD changed during validation')
    fail(remote_head(root,branch)==plan['head'],'Remote target advanced; refusing stale publication')
    if not plan['changed_paths']:
        receipt={'status':'ALREADY_CURRENT','promoted_this_run':False,'remote_write_performed':False,'verified_commit':plan['head'],'candidate_digest':plan['candidate_digest'],'time_utc':timestamp()}
        dump(root,OUT+'/PUBLICATION_RECEIPT.json',receipt);return receipt
    expected=set(plan['changed_paths'])
    dirty=set(git(root,'diff','--name-only').splitlines())
    fail(dirty<=expected,'Unexpected tracked modifications after validation')
    fail(not git(root,'diff','--cached','--name-only'),'Index already contains staged changes')
    payload_paths={x['path'] for x in decode_payload()['files']}
    fail(expected<=payload_paths,'Unapproved path in changed-path plan')
    receipt_path=f'provenance/actions/Q050/{run}-{attempt}.json'
    fail(not (root/receipt_path).exists(),'Refusing to overwrite an earlier installation record')
    dump(root,receipt_path,{'schema_version':1,'target_q':'Q050','accepted_model':'v0.12','dispatch_run_id':run,'dispatch_attempt':attempt,'base_commit':plan['head'],'scientific_base_commit':BASE,'candidate_digest':plan['candidate_digest'],'payload_sha256':PAYLOAD_SHA256,'validation':verification,'publication_state':'VALIDATED_RELEASE_TRANSACTION; actual remote result is in the Actions artifact PUBLICATION_RECEIPT.json','promotion_commit':None,'time_utc':timestamp()})
    subprocess.run(['git','config','user.name','github-actions[bot]'],cwd=root,check=True)
    subprocess.run(['git','config','user.email','41898282+github-actions[bot]@users.noreply.github.com'],cwd=root,check=True)
    subprocess.run(['git','add','--',*sorted(expected),receipt_path],cwd=root,check=True)
    staged=set(git(root,'diff','--cached','--name-only').splitlines())
    fail(staged==expected|{receipt_path},'Staged paths differ from validated release plan')
    staged_tree=verify_staged_candidate(root)
    subprocess.run(['git','commit','-m','Admit Q050 conditional literal-selector existence as model v0.12'],cwd=root,check=True)
    commit=git(root,'rev-parse','HEAD');tree=git(root,'rev-parse','HEAD^{tree}')
    fail(tree==staged_tree and git(root,'rev-parse','HEAD^')==plan['head'],'Committed tree/parent differs from validated transaction')
    receipt={'schema_version':1,'target_q':'Q050','version':'v0.12','base_commit':plan['head'],'promotion_commit':commit,'tree':tree,'candidate_digest':plan['candidate_digest'],'dispatch_run_id':run,'status':'PUSH_PENDING','remote_write_verified':False,'time_utc':timestamp()}
    dump(root,OUT+'/PUBLICATION_RECEIPT.json',receipt)
    try:
        # Normal fast-forward push: no force, no retry, no alternate destination.
        subprocess.run(['git','push','origin',commit+':refs/heads/'+branch],cwd=root,check=True)
        fail(remote_head(root,branch)==commit,'Remote ref does not equal committed candidate')
        subprocess.run(['git','fetch','origin','refs/heads/'+branch],cwd=root,check=True)
        fail(git(root,'rev-parse','FETCH_HEAD')==commit and git(root,'rev-parse','FETCH_HEAD^{tree}')==tree,'Fetched remote tree identity differs')
        candidate_digest(root)
        receipt.update(status='PROMOTED',remote_write_verified=True,time_utc=timestamp())
    except Exception as exc:
        receipt.update(status='PUBLICATION_FAILED_OR_UNVERIFIED',error=str(exc),time_utc=timestamp())
        dump(root,OUT+'/PUBLICATION_RECEIPT.json',receipt)
        raise
    dump(root,OUT+'/PUBLICATION_RECEIPT.json',receipt)
    print(json.dumps(receipt));return receipt

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    commands=parser.add_mutually_exclusive_group(required=True)
    commands.add_argument('--plan',action='store_true',help='Inspect preconditions without writing model state')
    commands.add_argument('--apply',action='store_true',help='Stage exact embedded candidate in this checkout')
    commands.add_argument('--validate',action='store_true',help='Execute repository validators and full unittest suite')
    commands.add_argument('--publish',action='store_true',help='Publish only inside manual mode=install dispatch')
    parser.add_argument('--root',type=Path,default=Path(__file__).resolve().parent)
    parser.add_argument('--branch',default='main')
    args=parser.parse_args();root=args.root.resolve()
    try:
        if args.plan:
            changes=preflight(root,decode_payload());print(json.dumps({'target_q':'Q050','changed_paths':changes,'remote_write_performed':False}))
        elif args.apply:apply(root)
        elif args.validate:validate(root)
        else:publish(root,args.branch)
    except Exception as exc:
        print('Q050_INSTALLATION_BLOCKED: '+str(exc),file=sys.stderr);return 1
    return 0

if __name__=='__main__':raise SystemExit(main())
